import{_ as o,C as d,o as e,c as A,a2 as a,b as r,w as i,a as n,E as l,a3 as s}from"./chunks/framework.DZUUNQ77.js";const C=JSON.parse('{"title":"StubActivity · 占位 Activity 族","description":"","frontmatter":{},"headers":[],"relativePath":"reference/client/stub-activity-family.md","filePath":"reference/client/stub-activity-family.md","lastUpdated":1784053534000}'),u={name:"reference/client/stub-activity-family.md"};function b(E,t,p,v,S,y){const c=d("Mermaid");return e(),A("div",null,[t[1]||(t[1]=a('<h1 id="stubactivity-·-占位-activity-族" tabindex="-1">StubActivity · 占位 Activity 族 <a class="header-anchor" href="#stubactivity-·-占位-activity-族" aria-label="Permalink to &quot;StubActivity · 占位 Activity 族&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">源码路径</p><p><a href="https://github.com/android-security-engineer/VirtualXposed-skills/blob/vxp/VirtualApp/lib/src/main/java/com/lody/virtual/client/stub/StubActivity.java" target="_blank" rel="noreferrer"><code>src/main/java/com/lody/virtual/client/stub/StubActivity.java</code></a></p></div><p><code>StubActivity</code> 是欺骗真实 AMS 清单检查的占位 Activity。它在宿主 Manifest 里预声明了 <strong>N 个内部子类</strong>（<code>C0</code>~<code>CN</code>），真实系统看到的是这些合法的宿主组件，运行时再用 H Callback 把 Intent 还原成虚拟 App 的真实 Activity。</p><h2 id="为什么要-100-个存根" tabindex="-1">为什么要 100 个存根 <a class="header-anchor" href="#为什么要-100-个存根" aria-label="Permalink to &quot;为什么要 100 个存根&quot;">​</a></h2><p>真实 AMS 启动 Activity 前会检查「目标组件是否在调用方 Manifest」。虚拟 App 的 Activity 不在宿主 Manifest 里，直接 <code>startActivity</code> 会被拒。解法：</p><ol><li>虚拟 AMS 把真实 Intent 换成指向 <code>StubActivity.C{index}</code> 的 Stub Intent。</li><li><code>StubActivity.C{index}</code> 在宿主 Manifest 里声明过，AMS 清单检查通过。</li><li>真实 AMS 启动 <code>StubActivity.C{index}</code>。</li><li>主线程 H Callback 拦到 <code>LAUNCH_ACTIVITY</code>，把 Stub Intent 还原成真实 Intent，反射创建真实 Activity。</li></ol><p>存根数量（<code>STUB_COUNT</code>，默认 50）要够容纳并发任务栈，每个并发 Activity 占一个槽位，避免复用冲突。</p><h2 id="stub-activity-启动与还原" tabindex="-1">Stub Activity 启动与还原 <a class="header-anchor" href="#stub-activity-启动与还原" aria-label="Permalink to &quot;Stub Activity 启动与还原&quot;">​</a></h2>',8)),(e(),r(s,null,{default:i(()=>[l(c,{id:"mermaid-45",class:"mermaid",graph:"sequenceDiagram%0A%20%20participant%20App%20as%20%E8%99%9A%E6%8B%9F%20App%0A%20%20participant%20VAMS%20as%20%E8%99%9A%E6%8B%9F%20AMS%0A%20%20participant%20AMS%20as%20%E7%9C%9F%E5%AE%9E%20AMS%0A%20%20participant%20Stub%20as%20StubActivity.C%7Bi%7D%0A%20%20participant%20H%20as%20%E4%B8%BB%E7%BA%BF%E7%A8%8B%20H%20Callback%0A%20%20App-%3E%3EVAMS%3A%20startActivity(%E7%9C%9F%E5%AE%9E%20Intent)%0A%20%20VAMS-%3E%3EVAMS%3A%20%E6%8D%A2%E6%88%90%20Stub%20Intent(C%7Bindex%7D)%0A%20%20VAMS-%3E%3EAMS%3A%20%E5%90%AF%E5%8A%A8%20StubActivity.C%7Bindex%7D%0A%20%20Note%20over%20AMS%3A%20%E6%B8%85%E5%8D%95%E6%A3%80%E6%9F%A5%E9%80%9A%E8%BF%87(%E5%AD%98%E6%A0%B9%E5%9C%A8%E5%AE%BF%E4%B8%BB%20Manifest)%0A%20%20AMS-%3E%3EStub%3A%20LAUNCH_ACTIVITY%0A%20%20Stub-%3E%3EH%3A%20%E6%8B%A6%E6%88%AA%20LAUNCH_ACTIVITY%0A%20%20H-%3E%3EH%3A%20%E8%BF%98%E5%8E%9F%E7%9C%9F%E5%AE%9E%20Intent%0A%20%20H-%3E%3EApp%3A%20%E5%8F%8D%E5%B0%84%E5%88%9B%E5%BB%BA%E7%9C%9F%E5%AE%9E%20Activity%0A"})]),fallback:i(()=>[...t[0]||(t[0]=[n(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<h2 id="变体" tabindex="-1">变体 <a class="header-anchor" href="#变体" aria-label="Permalink to &quot;变体&quot;">​</a></h2><p><code>StubActivity</code> 是抽象基类，子类 <code>C0</code>~<code>CN</code> 只是占位（空实现）。还有几个语义变体：</p><table tabindex="0"><thead><tr><th>类</th><th>语义</th></tr></thead><tbody><tr><td><a href="./stub-dialog"><code>StubDialog</code></a></td><td>Dialog 风格存根（透明/弹窗主题）</td></tr><tr><td><a href="./stub-exclude-recent"><code>StubExcludeFromRecentActivity</code></a></td><td>不进最近任务列表的存根</td></tr><tr><td><a href="./stub-pending"><code>StubPendingActivity</code></a></td><td>PendingIntent 用的存根</td></tr></tbody></table><h2 id="oncreate" tabindex="-1">onCreate <a class="header-anchor" href="#oncreate" aria-label="Permalink to &quot;onCreate&quot;">​</a></h2><p><code>StubActivity.onCreate</code> 本身不创建 UI——真正的 Activity 创建发生在 H Callback 里。Stub 只是把启动信号传出去。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="./../../features/stub-activity">Stub Activity 机制</a>：完整原理。</li><li><a href="./va-settings"><code>VASettings</code></a>：<code>STUB_COUNT</code>、<code>getStubActivityName(index)</code>。</li><li><a href="./hook-delegate"><code>H Callback</code> 还原</a>：Intent 还原发生处。</li></ul>',7))])}const _=o(u,[["render",b]]);export{C as __pageData,_ as default};
